#!/usr/bin/env node
/**
 * send-sample.mjs — POST a wearable vendor's documented webhook example to
 * a local URL, signed the way that vendor documents, to test your handler.
 *
 *   node send-sample.mjs --list
 *   node send-sample.mjs <vendor> [event] --url http://localhost:3000/webhook [--secret <secret>] [--dry-run]
 *
 * From https://aifitnessapi.com/webhooks (source and rules per vendor there).
 * GENERATED by scripts/build-webhook-sender.mjs from src/data/webhookPayloads.ts
 * in the aifitnessapi repository: do not edit by hand.
 *
 * Zero dependencies: Node 18 or newer (global fetch, node:crypto). It sends
 * only to localhost, 127.0.0.1 or ::1 unless you pass --allow-remote, and it
 * sends nothing at all with --dry-run.
 *
 * The bodies are the vendors' own published examples, unchanged except where
 * the vendor prints a placeholder for your secret (Wahoo's <webhook_token>).
 * Signatures are computed now, with your --secret (default: the demo secret
 * aifitnessapi.com/tools/webhook-verifier uses, so a request printed with
 * --dry-run can be pasted there and verifies):
 *
 *   oura      HMAC-SHA256(secret, x-oura-timestamp + JSON.stringify(body)), hex upper-case
 *   whoop     base64 HMAC-SHA256(secret, X-WHOOP-Signature-Timestamp (ms) + raw body)
 *   terra     X-Terra-Signature: t=<seconds>,v1=hex HMAC-SHA256(secret, t + "." + raw body)
 *   polar     Polar-Webhook-Signature: hex HMAC-SHA256(secret, raw body)
 *   strava    unsigned (Strava documents no signature for events)
 *   withings  unsigned form body; your secret goes on the URL as ?token=
 *   wahoo     unsigned; your secret is the body's webhook_token
 *   google-health  Authorization header with your secret. The real
 *             GOOGLE-HEALTH-API-SIGNATURE header is signed with Google's
 *             private key, so this script cannot produce it and sends none.
 */
