export const DEMO_SECRET = "demo-secret-not-a-real-key";

const hmac = (secret, msg) => createHmac("sha256", secret).update(msg, "utf8").digest();

function isLocal(url) {
  const h = new URL(url).hostname.replace(/^\[|\]$/g, "");
  return h === "localhost" || h === "127.0.0.1" || h === "::1";
}

/** Build the request for one documented event. Exported for tests; sends nothing. */
export function buildRequest(vendorId, eventId, { url, secret = DEMO_SECRET, now = Date.now() } = {}) {
  const vendor = SAMPLES[vendorId];
  if (!vendor) throw new Error(`Unknown vendor "${vendorId}". Run with --list.`);
  const event = eventId ? vendor.events.find((e) => e.id === eventId) : vendor.events[0];
  if (!event) throw new Error(`Unknown event "${eventId}" for ${vendorId}. Run with --list.`);
  const headers = { "Content-Type": event.contentType, "User-Agent": "aifitnessapi-send-sample/1" };
  let body = typeof event.body === "string" ? event.body : JSON.stringify(event.body);
  let target = url;
  const sec = Math.floor(now / 1000);
  switch (vendor.scheme) {
    case "oura": {
      const ts = String(sec);
      headers["x-oura-timestamp"] = ts;
      headers["x-oura-signature"] = hmac(secret, ts + JSON.stringify(JSON.parse(body))).toString("hex").toUpperCase();
      break;
    }
    case "whoop": {
      const ts = String(now);
      headers["X-WHOOP-Signature-Timestamp"] = ts;
      headers["X-WHOOP-Signature"] = hmac(secret, ts + body).toString("base64");
      break;
    }
    case "terra": {
      headers["X-Terra-Signature"] = `t=${sec},v1=${hmac(secret, `${sec}.${body}`).toString("hex")}`;
      break;
    }
    case "polar": {
      headers["Polar-Webhook-Event"] = JSON.parse(body).event;
      headers["Polar-Webhook-Signature"] = hmac(secret, body).toString("hex");
      break;
    }
    case "withings": {
      const u = new URL(url);
      u.searchParams.set("token", secret);
      target = u.toString();
      break;
    }
    case "wahoo": {
      body = JSON.stringify(JSON.parse(body.replace("<webhook_token>", JSON.stringify(secret))));
      break;
    }
    case "google-health": {
      headers.Authorization = /^bearer /i.test(secret) ? secret : `Bearer ${secret}`;
      break;
    }
    case "strava":
      break;
    default:
      throw new Error(`No signing rule for ${vendorId}`);
  }
  return { method: "POST", url: target, headers, body, vendor: vendorId, event: event.id };
}

function list() {
  for (const [id, v] of Object.entries(SAMPLES)) {
    console.log(`${id}  (${v.name})`);
    for (const e of v.events) console.log(`  ${e.id.padEnd(30)} ${e.title}`);
  }
}

function parseArgs(argv) {
  const out = { positional: [] };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--url" || a === "--secret") out[a.slice(2)] = argv[++i];
    else if (a.startsWith("--")) out[a.slice(2)] = true;
    else out.positional.push(a);
  }
  return out;
}

async function main(argv) {
  const args = parseArgs(argv);
  if (args.list || args.help || !args.positional.length) {
    if (!args.list) console.log("usage: node send-sample.mjs <vendor> [event] --url http://localhost:3000/webhook [--secret s] [--dry-run]\n");
    list();
    return 0;
  }
  const [vendorId, eventId] = args.positional;
  const url = args.url ?? "http://localhost:3000/webhook";
  if (!isLocal(url) && !args["allow-remote"]) {
    console.error(`Refusing to send to ${url}: not localhost. Pass --allow-remote to override.`);
    return 2;
  }
  const req = buildRequest(vendorId, eventId, { url, secret: args.secret ?? DEMO_SECRET });
  console.log(`${req.method} ${req.url}`);
  for (const [k, v] of Object.entries(req.headers)) console.log(`${k}: ${v}`);
  console.log(`\n${req.body}\n`);
  if (args["dry-run"]) return 0;
  const res = await fetch(req.url, { method: "POST", headers: req.headers, body: req.body });
  const text = await res.text();
  console.log(`← ${res.status} ${res.statusText}${text ? `\n${text.slice(0, 2000)}` : ""}`);
  return res.ok ? 0 : 1;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main(process.argv.slice(2)).then(
    (code) => process.exit(code),
    (e) => {
      console.error(e.message);
      process.exit(2);
    },
  );
}
